-- =========================================================================================
-- SMARTSTAY ENTERPRISE EXTENSION - NÂNG CẤP HỆ SINH THÁI CƠ SỞ DỮ LIỆU THÔNG MINH
-- Cơ sở dữ liệu: SmartStayDB (Microsoft SQL Server 2022)
-- Máy chủ: MSI-Bao\SQLEXPRESS
-- =========================================================================================




-- 1. Phân hệ Quản lý Giường / Sleepbox cho mô hình Ký túc xá thông minh & Co-Living

    CREATE TABLE IF NOT EXISTS "Giuong" (
        "MaGiuong" INT GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
        "MaPhong" INT NOT NULL,
        "KyHieuGiuong" VARCHAR(50) NOT NULL, -- G.01, G.02, Tầng 1, Tầng 2
        "GiaThueThang" DECIMAL(18,2) NOT NULL DEFAULT 1500000.00,
        "TrangThai" VARCHAR(40) NOT NULL DEFAULT 'Trống', -- Trống, Đang ở, Đã đặt, Bảo trì
        "GhiChu" VARCHAR(500) NULL,
        CONSTRAINT "FK_Giuong_Phong" FOREIGN KEY ("MaPhong") REFERENCES "Phong"("MaPhong") ON DELETE CASCADE
    );



-- 2. Phân hệ Thiết bị IoT & Khóa cửa thông minh (Smart Lock, IoT Energy Meter)

    CREATE TABLE IF NOT EXISTS "ThietBiIoT" (
        "MaThietBiIoT" INT GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
        "MaPhong" INT NULL,
        "MaToaNha" INT NOT NULL,
        "TenThietBi" VARCHAR(150) NOT NULL,
        "LoaiThietBi" VARCHAR(50) NOT NULL, -- KhoaCuaThongMinh, CongToDienTu, CamBienKhoi, MayLanhIoT
        "MaSeri" VARCHAR(100) NOT NULL UNIQUE,
        "DiaChiMac" VARCHAR(50) NULL,
        "MatKhauTruyCap" VARCHAR(255) NULL,
        "TrangThaiHoatDong" VARCHAR(30) NOT NULL DEFAULT 'Online', -- Online, Offline, CanhBaoPin
        "MucPin" INT NULL, -- % pin của khóa cửa
        "LanDongBoCuoi" TIMESTAMP NULL,
        CONSTRAINT "FK_IoT_Phong" FOREIGN KEY ("MaPhong") REFERENCES "Phong"("MaPhong") ON DELETE SET NULL,
        CONSTRAINT "FK_IoT_ToaNha" FOREIGN KEY ("MaToaNha") REFERENCES "ToaNha"("MaToaNha")
    );



-- 3. Nhật ký mở cửa & Truy cập an ninh (Access Log)

    CREATE TABLE IF NOT EXISTS "LichSuTruyCapCua" (
        "MaLichSuTruyCap" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
        "MaThietBiIoT" INT NOT NULL,
        "MaNguoiDung" INT NULL,
        "PhuongThucMo" VARCHAR(50) NOT NULL, -- VanTay, TheTu, MatMaTamThoi, MoTuXaQuaApp, NhanDienKhuonMat
        "ThoiDiemMo" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
        "ThanhCong" BOOLEAN NOT NULL DEFAULT TRUE,
        "GhiChu" VARCHAR(255) NULL,
        CONSTRAINT "FK_LSTC_IoT" FOREIGN KEY ("MaThietBiIoT") REFERENCES "ThietBiIoT"("MaThietBiIoT") ON DELETE CASCADE,
        CONSTRAINT "FK_LSTC_NguoiDung" FOREIGN KEY ("MaNguoiDung") REFERENCES "NguoiDung"("MaNguoiDung") ON DELETE SET NULL
    );



-- 4. Phân hệ Phương tiện & Thẻ gửi xe cư dân

    CREATE TABLE IF NOT EXISTS "PhuongTienCuDan" (
        "MaPhuongTien" INT GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
        "MaCuDan" INT NOT NULL,
        "LoaiXe" VARCHAR(50) NOT NULL DEFAULT 'Xe máy', -- Xe máy, Xe đạp điện, Ô tô
        "BienSoXe" VARCHAR(30) NOT NULL,
        "NhanHieu" VARCHAR(100) NULL, -- Honda Vision, Yamaha Grande...
        "MauXe" VARCHAR(50) NULL,
        "MaTheXeRFID" VARCHAR(50) NULL,
        "PhiGuiXeHangThang" DECIMAL(18,2) NOT NULL DEFAULT 120000.00,
        "DuongDanAnhDangKyXe" VARCHAR(600) NULL,
        "DangHoatDong" BOOLEAN NOT NULL DEFAULT TRUE,
        "NgayDangKy" DATE NOT NULL DEFAULT CAST(CURRENT_TIMESTAMP AS DATE),
        CONSTRAINT "FK_PT_CuDan" FOREIGN KEY ("MaCuDan") REFERENCES "CuDan"("MaCuDan") ON DELETE CASCADE
    );



-- 5. Phân hệ Đặt giữ chỗ phòng trực tuyến (Booking / Reservation)

    CREATE TABLE IF NOT EXISTS "PhieuDatGiuCho" (
        "MaPhieuDat" INT GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
        "SoPhieuDat" VARCHAR(50) NOT NULL UNIQUE,
        "MaPhong" INT NOT NULL,
        "MaGiuong" INT NULL,
        "HoTenKhach" VARCHAR(150) NOT NULL,
        "SoDienThoai" VARCHAR(30) NOT NULL,
        "Email" VARCHAR(150) NULL,
        "SoCCCD" VARCHAR(40) NULL,
        "TienCocGiuCho" DECIMAL(18,2) NOT NULL,
        "NgayDat" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
        "HanGiuCho" TIMESTAMP NOT NULL,
        "NgayDuKienNhanPhong" DATE NOT NULL,
        "TrangThai" VARCHAR(40) NOT NULL DEFAULT 'Chờ nhận phòng', -- Chờ nhận phòng, Đã nhận phòng, Đã hủy cọc, Hết hạn
        "GhiChu" VARCHAR(500) NULL,
        CONSTRAINT "FK_DatCho_Phong" FOREIGN KEY ("MaPhong") REFERENCES "Phong"("MaPhong"),
        CONSTRAINT "FK_DatCho_Giuong" FOREIGN KEY ("MaGiuong") REFERENCES "Giuong"("MaGiuong")
    );



-- 6. Phân hệ Webhook Ngân hàng Tự động Gạch nợ (SePAY / Casso / Bank Auto-Reconciliation)

    CREATE TABLE IF NOT EXISTS "WebhookGiaoDichNganHang" (
        "MaGiaoDichNganHang" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
        "MaThamChieuNganHang" VARCHAR(150) NOT NULL UNIQUE, -- Mã FT giao dịch
        "SoTien" DECIMAL(18,2) NOT NULL,
        "NoiDungChuyenKhoan" VARCHAR(500) NOT NULL,
        "ThoiGianGiaoDich" TIMESTAMP NOT NULL,
        "SoTaiKhoanNhan" VARCHAR(50) NOT NULL,
        "MaHoaDonKhop" INT NULL,
        "TrangThaiKhop" VARCHAR(40) NOT NULL DEFAULT 'Chưa khớp', -- Đã khớp tự động, Đã khớp thủ công, Không tìm thấy hóa đơn
        "ThoiDiemNhanWebhook" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
        CONSTRAINT "FK_Webhook_HoaDon" FOREIGN KEY ("MaHoaDonKhop") REFERENCES "HoaDon"("MaHoaDon") ON DELETE SET NULL
    );



-- 7. Phân hệ Ví Cư Dân & Thanh Toán Nội Khu (Resident Wallet)

    CREATE TABLE IF NOT EXISTS "ViCuDan" (
        "MaVi" INT GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
        "MaCuDan" INT NOT NULL UNIQUE,
        "SoDuKhaDung" DECIMAL(18,2) NOT NULL DEFAULT FALSE.00,
        "TrangThaiKhoa" BOOLEAN NOT NULL DEFAULT FALSE,
        "CapNhatCuoi" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
        CONSTRAINT "FK_Vi_CuDan" FOREIGN KEY ("MaCuDan") REFERENCES "CuDan"("MaCuDan") ON DELETE CASCADE
    );




    CREATE TABLE IF NOT EXISTS "LichSuGiaoDichVi" (
        "MaGiaoDichVi" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
        "MaVi" INT NOT NULL,
        "LoaiGiaoDich" VARCHAR(50) NOT NULL, -- NapTienVietQR, TruTienDienNuoc, TruTienDichVu, HoanTienCoc
        "SoTien" DECIMAL(18,2) NOT NULL,
        "SoDuTruoc" DECIMAL(18,2) NOT NULL,
        "SoDuSau" DECIMAL(18,2) NOT NULL,
        "MaHoaDonLienQuan" INT NULL,
        "NoiDung" VARCHAR(300) NOT NULL,
        "ThoiGian" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
        CONSTRAINT "FK_LSVi_Vi" FOREIGN KEY ("MaVi") REFERENCES "ViCuDan"("MaVi") ON DELETE CASCADE
    );



-- 8. Phân hệ Quản lý Sổ Quỹ Thu Chi Tòa Nhà (Cash Flow Management)

    CREATE TABLE IF NOT EXISTS "SoQuyThuChi" (
        "MaPhieuThuChi" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
        "SoChungTu" VARCHAR(50) NOT NULL UNIQUE,
        "MaToaNha" INT NOT NULL,
        "LoaiPhieu" VARCHAR(20) NOT NULL, -- PhieuThu, PhieuChi
        "HangMuc" VARCHAR(100) NOT NULL, -- ThuTienPhong, ThuDienNuoc, ChiTienDienEVN, ChiTienNuoc, ChiLuongTapVu, ChiSuaChua
        "SoTien" DECIMAL(18,2) NOT NULL,
        "HinhThuc" VARCHAR(50) NOT NULL DEFAULT 'Chuyển khoản', -- Tiền mặt, Chuyển khoản, VietQR
        "NguoiNopNhan" VARCHAR(150) NOT NULL,
        "NoiDung" VARCHAR(500) NOT NULL,
        "NgayChungTu" DATE NOT NULL,
        "NguoiLapPhieu" INT NOT NULL,
        "ThoiDiemTao" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
        CONSTRAINT "FK_SQ_ToaNha" FOREIGN KEY ("MaToaNha") REFERENCES "ToaNha"("MaToaNha"),
        CONSTRAINT "FK_SQ_NguoiDung" FOREIGN KEY ("NguoiLapPhieu") REFERENCES "NguoiDung"("MaNguoiDung")
    );



-- 9. Phân hệ Kho Vật tư & Linh kiện Bảo trì kỹ thuật

    CREATE TABLE IF NOT EXISTS "VatTuLinhKien" (
        "MaVatTu" INT GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
        "MaToaNha" INT NOT NULL,
        "TenVatTu" VARCHAR(150) NOT NULL,
        "DonViTinh" VARCHAR(30) NOT NULL, -- Cái, Bộ, Mét, Cuộn, Bình
        "SoLuongTon" INT NOT NULL DEFAULT FALSE,
        "DonGiaNhap" DECIMAL(18,2) NOT NULL DEFAULT FALSE.00,
        "GiaXuatSuaChua" DECIMAL(18,2) NOT NULL DEFAULT FALSE.00,
        "DinhMucToiThieu" INT NOT NULL DEFAULT 5, -- Cảnh báo sắp hết hàng
        CONSTRAINT "FK_VT_ToaNha" FOREIGN KEY ("MaToaNha") REFERENCES "ToaNha"("MaToaNha")
    );




    CREATE TABLE IF NOT EXISTS "PhieuXuatVatTuSuCo" (
        "MaXuatVatTu" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
        "MaPhieuSuCo" INT NOT NULL,
        "MaVatTu" INT NOT NULL,
        "SoLuongXuat" INT NOT NULL DEFAULT TRUE,
        "DonGia" DECIMAL(18,2) NOT NULL,
        "ThanhTien" AS ("SoLuongXuat" * "DonGia"),
        "ThoiDiemXuat" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
        CONSTRAINT "FK_XVTSC_PhieuSuCo" FOREIGN KEY ("MaPhieuSuCo") REFERENCES "PhieuSuCo"("MaPhieuSuCo") ON DELETE CASCADE,
        CONSTRAINT "FK_XVTSC_VatTu" FOREIGN KEY ("MaVatTu") REFERENCES "VatTuLinhKien"("MaVatTu")
    );



-- 10. Phân hệ Cơ sở Tri thức Trợ lý AI (Gemini RAG Knowledge Base)

    CREATE TABLE IF NOT EXISTS "TriThucAiRAG" (
        "MaTriThuc" INT GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
        "ChuDe" VARCHAR(100) NOT NULL, -- NoiQuyToaNha, CachTinhDienNuoc, HuongDanSuDungThietBi, ThuTucTamTru
        "CauHoiPhoBien" VARCHAR(500) NOT NULL,
        "NoiDungGiaiDap" VARCHAR(MAX) NOT NULL,
        "DoUuTien" INT NOT NULL DEFAULT TRUE,
        "DangHoatDong" BOOLEAN NOT NULL DEFAULT TRUE,
        "NgayCapNhat" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
    );



-- =========================================================================================
-- INDEXES TỐI ƯU HIỆU NĂNG CHO CÁC BẢNG TRỌNG TÂM
-- =========================================================================================
IF NOT EXISTS (SELECT * FROM sys.indexes WHERE name = 'IX_Phong_TrangThai')
    CREATE NONCLUSTERED INDEX "IX_Phong_TrangThai" ON "Phong"("TrangThai", "SoTang");

IF NOT EXISTS (SELECT * FROM sys.indexes WHERE name = 'IX_HoaDon_TrangThai_KyTinhTien')
    CREATE NONCLUSTERED INDEX "IX_HoaDon_TrangThai_KyTinhTien" ON "HoaDon"("TrangThai", "KyTinhTien");

IF NOT EXISTS (SELECT * FROM sys.indexes WHERE name = 'IX_PhieuSuCo_TrangThai_UuTien')
    CREATE NONCLUSTERED INDEX "IX_PhieuSuCo_TrangThai_UuTien" ON "PhieuSuCo"("TrangThai", "UuTien");

IF NOT EXISTS (SELECT * FROM sys.indexes WHERE name = 'IX_ThanhToan_TrangThai')
    CREATE NONCLUSTERED INDEX "IX_ThanhToan_TrangThai" ON "ThanhToan"("TrangThai");


-- =========================================================================================
-- VIEWS BÁO CÁO TỔNG HỢP & THỜI GIAN THỰC
-- =========================================================================================

-- View 1: Báo cáo Doanh thu & Công nợ tổng hợp theo Tòa nhà
CREATE OR ALTER VIEW "v_BaoCaoDoanhThuTheoToaNha"
AS
SELECT 
    t."MaToaNha",
    t."TenToaNha",
    h."KyTinhTien",
    COUNT(h."MaHoaDon") AS "TongSoHoaDon",
    SUM(h."TongTien") AS "TongTienPhatHanh",
    SUM(CASE WHEN h."TrangThai" = 'Đã thanh toán' THEN h."TongTien" ELSE 0 ) AS "DoanhThuDaThu",
    SUM(CASE WHEN h."TrangThai" != 'Đã thanh toán' THEN h."TongTien" ELSE 0 ) AS "CongNoConLai",
    CAST(ROUND((SUM(CASE WHEN h."TrangThai" = 'Đã thanh toán' THEN h."TongTien" ELSE 0 ) * 100.0) / NULLIF(SUM(h."TongTien"), 0), 1) AS DECIMAL(5,1)) AS "TyLeThuHoi"
FROM "HoaDon" h
INNER JOIN "HopDong" hd ON h."MaHopDong" = hd."MaHopDong"
INNER JOIN "Phong" p ON hd."MaPhong" = p."MaPhong"
INNER JOIN "ToaNha" t ON p."MaToaNha" = t."MaToaNha"
GROUP BY t."MaToaNha", t."TenToaNha", h."KyTinhTien";


-- View 2: Sơ đồ phòng tổng hợp thời gian thực kèm công nợ và thông tin cư dân
CREATE OR ALTER VIEW "v_SoDoPhongRealTime"
AS
SELECT 
    p."MaPhong",
    p."KyHieuPhong",
    p."SoTang",
    p."DienTich",
    p."SucChua",
    p."GiaThue",
    p."TrangThai" AS "TrangThaiPhong",
    t."MaToaNha",
    t."TenToaNha",
    lp."TenLoaiPhong",
    hd."MaHopDong",
    hd."SoHopDong",
    u."HoTen" AS "TenCuDanDaiDien",
    u."SoDienThoai" AS "SdtCuDan",
    ISNULL(debt."CongNoChuaThu", 0) AS "CongNoChuaThu",
    ISNULL(ticket."SoSuCoChuaXong", 0) AS "SoSuCoChuaXong"
FROM "Phong" p
INNER JOIN "ToaNha" t ON p."MaToaNha" = t."MaToaNha"
INNER JOIN "LoaiPhong" lp ON p."MaLoaiPhong" = lp."MaLoaiPhong"
LEFT JOIN "HopDong" hd ON p."MaPhong" = hd."MaPhong" AND hd."TrangThai" = 'Đang hiệu lực'
LEFT JOIN "CuDanHopDong" cdhd ON hd."MaHopDong" = cdhd."MaHopDong" AND cdhd."LaDaiDien" = 1
LEFT JOIN "CuDan" c ON cdhd."MaCuDan" = c."MaCuDan"
LEFT JOIN "NguoiDung" u ON c."MaNguoiDung" = u."MaNguoiDung"
LEFT JOIN (
    SELECT hd_sub."MaPhong", SUM(h_sub."TongTien") AS "CongNoChuaThu"
    FROM "HoaDon" h_sub
    INNER JOIN "HopDong" hd_sub ON h_sub."MaHopDong" = hd_sub."MaHopDong"
    WHERE h_sub."TrangThai" != 'Đã thanh toán'
    GROUP BY hd_sub."MaPhong"
) debt ON p."MaPhong" = debt."MaPhong"
LEFT JOIN (
    SELECT "MaPhong", COUNT("MaPhieuSuCo") AS "SoSuCoChuaXong"
    FROM "PhieuSuCo"
    WHERE "TrangThai" IN ('Chờ xử lý', 'Đang sửa')
    GROUP BY "MaPhong"
) ticket ON p."MaPhong" = ticket."MaPhong";


-- =========================================================================================
-- TRIGGER TỰ ĐỘNG GHI NHẬT KÝ KHI THAY ĐỔI TRẠNG THÁI SỰ CỐ KANBAN
-- =========================================================================================
CREATE OR ALTER TRIGGER "trg_PhieuSuCo_GhiNhatKyKanban"
ON "PhieuSuCo"
AFTER UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    
    IF UPDATE("TrangThai")
    BEGIN
        INSERT INTO "LichSuSuCo" (
            "MaPhieuSuCo",
            "TrangThaiCu",
            "TrangThaiMoi",
            "NguoiThayDoi",
            "ThoiDiemThayDoi",
            "GhiChu"
        )
        SELECT 
            i."MaPhieuSuCo",
            d."TrangThai",
            i."TrangThai",
            ISNULL(i."NguoiDuocGiao", 1),
            CURRENT_TIMESTAMP,
            'Hệ thống tự động ghi nhật ký dịch chuyển thẻ Kanban: ' + d."TrangThai" + ' -> ' + i."TrangThai"
        FROM inserted i
        INNER JOIN deleted d ON i."MaPhieuSuCo" = d."MaPhieuSuCo"
        WHERE i."TrangThai" <> d."TrangThai";
    
;


-- =========================================================================================
-- STORED PROCEDURE TÍNH TOÁN BẬC THANG & PHÁT HÀNH HÓA ĐƠN HÀNG LOẠT
-- =========================================================================================
CREATE OR ALTER PROCEDURE "sp_PhatHanhHoaDonThangTuDong"
    @KyTinhTien DATE,
    @MaNguoiTao INT
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRANSACTION;
    
    BEGIN TRY
        -- Khai báo bảng tạm lưu kết quả
        DECLARE @HoaDonMoi TABLE (
            "MaHoaDon" INT,
            "MaHopDong" INT,
            "MaPhong" INT
        );

        -- Tự động sinh mã hóa đơn và tạo bản ghi cho tất cả hợp đồng đang hiệu lực
        INSERT INTO "HoaDon" (
            "SoHoaDon",
            "MaHopDong",
            "KyTinhTien",
            "NgayPhatHanh",
            "NgayDenHan",
            "TongTien",
            "TrangThai",
            "NoiDungQR",
            "DuongDanQR",
            "NguoiTao",
            "ThoiDiemTao"
        )
        SELECT 
            'HD-' + FORMAT(@KyTinhTien, 'yyyyMM') + '-' + p."KyHieuPhong",
            hd."MaHopDong",
            @KyTinhTien,
            CAST(CURRENT_TIMESTAMP AS DATE),
            DATEADD(DAY, 5, CAST(CURRENT_TIMESTAMP AS DATE)),
            hd."TienThueHangThang", -- Tạm thời khởi tạo bằng tiền thuê phòng
            'Chưa thanh toán',
            'HD ' + p."KyHieuPhong" + ' ' + FORMAT(@KyTinhTien, 'MM/yyyy'),
            'https://img.vietqr.io/image/970422-0987654321-compact2.png?amount=' + CAST(CAST(ROUND(hd."TienThueHangThang", 0) AS BIGINT) AS VARCHAR(30)) + '&addInfo=HD%20' + p."KyHieuPhong" + '&accountName=SMARTSTAY',
            @MaNguoiTao,
            CURRENT_TIMESTAMP
        FROM "HopDong" hd
        INNER JOIN "Phong" p ON hd."MaPhong" = p."MaPhong"
        WHERE hd."TrangThai" = 'Đang hiệu lực'
          AND NOT EXISTS (
              SELECT 1 FROM "HoaDon" h_check 
              WHERE h_check."MaHopDong" = hd."MaHopDong" AND h_check."KyTinhTien" = @KyTinhTien
          );

        COMMIT TRANSACTION;
        SELECT @@ROWCOUNT AS "SoHoaDonDaTaoThanhCong";
     TRY
    BEGIN CATCH
        ROLLBACK TRANSACTION;
        THROW;
     CATCH
;

